function loginPage(){return `<div class="login"><div class="card login-card"><div class="brand-mark">KS</div><span class="eyebrow">PRIVATE WORKSPACE</span><h1>欢迎回来</h1><p>登录 KOL Seeding Workbench，继续管理 Campaign 与达人资产。</p><div class="field"><label>工作邮箱</label><input id="loginEmail" type="email" placeholder="name@company.com" value="demo@company.com"></div><div class="field"><label>密码</label><input id="loginPassword" type="password" placeholder="请输入密码" value="demo2026"></div><button class="primary" id="loginBtn">登录工作台 →</button><div class="hint">演示版本：输入任意邮箱和密码即可进入。真实账号认证将在后端接入后启用。</div></div></div>`}
function renderNav(){nav.innerHTML=navSections.map(s=>`<div class="nav-section"><div class="nav-label">${s.label}</div>${s.items.map(i=>`<button class="nav-item ${route===i[0]?'active':''}" data-route="${i[0]}"><span class="nav-icon">${i[1]}</span><span>${i[2]}</span></button>`).join('')}</div>`).join('')}
const head=(e,t,d,a='')=>`<div class="page-head"><div><span class="eyebrow">${e}</span><h1>${t}</h1><p>${d}</p></div>${a}</div>`;
const badge=(t,c='blue')=>`<span class="badge ${c}">${t}</span>`;
function dashboard(){const order=p=>p.urgency==='overdue'?0:p.pinned?1:p.urgency==='urgent'?2:p.urgency==='soon'?3:4;const sorted=[...dashboardProjects].sort((a,b)=>order(a)-order(b));const cards=sorted.map(p=>{const progress=Math.round(p.completed/p.total*100);return `<article class="campaign-card" data-dashboard-card data-urgency="${p.urgency}"><div class="campaign-top"><div class="campaign-title"><div class="campaign-flags"><span class="urgency-tag ${p.urgency}"><i></i>${p.urgencyLabel}</span>${p.pinned?'<button class="pin active" data-action="toast" data-message="重点项目已置顶" title="重点项目">★ 重点</button>':''}</div><h3>${p.name}</h3><p>${p.client} · ${p.owner} 负责</p></div><div class="campaign-meta"><div class="owner-avatar">${p.initial}</div><div><small>项目截止</small><strong>${p.due}</strong><span class="${p.urgency==='overdue'?'danger-text':''}">${p.dueNote}</span></div></div></div><div class="campaign-body"><div class="stage-block"><div class="stage-label"><span>当前阶段</span><strong>${p.stage}</strong></div><div class="project-progress"><div class="bar"><span style="width:${progress}%"></span></div><b>${progress}%</b></div><small>已完成 ${p.completed} / ${p.total} 个启用节点</small></div><div class="next-block"><span>下一节点</span><strong>${p.next}</strong><small>截止 ${p.nextDue}</small></div><button class="project-open ghost" data-route="project-detail">进入项目 →</button></div><div class="campaign-footer"><button class="task-toggle" data-project-toggle aria-expanded="false"><span>任务清单</span><b>${p.tasks.filter(t=>t[3]!=='done').length} 项待处理</b><i>⌄</i></button><div class="task-panel">${p.tasks.map(t=>`<div class="task-item"><span class="task-status ${t[3]}">${t[3]==='done'?'✓':''}</span><strong>${t[0]}</strong><span>${t[1]}</span><small>${t[2]}</small></div>`).join('')}</div></div></article>`}).join('');return `${head('TEAM CONTROL CENTER','我的项目','这里只显示我负责或参与的项目；协作项目会同步更新。','<button class="primary" data-route="new-project">＋ 新建项目</button>')}<div class="dashboard-summary"><div><span>进行中</span><strong>${dashboardProjects.length}</strong><small>个项目</small></div><div><span>需要立即处理</span><strong class="danger-text">2</strong><small>个项目</small></div><div><span>今日待办</span><strong>6</strong><small>项任务</small></div><div class="summary-note"><b>排序规则</b><span>已逾期 → 重点 → 3 天内 → 7 天内 → 正常</span></div></div><div class="dashboard-toolbar"><div><h2>进行中的项目</h2><p>进度根据已完成的启用节点自动计算</p></div><div class="filter-chips"><button class="active" data-dash-filter="all">全部</button><button data-dash-filter="attention">需要关注</button><button data-dash-filter="pinned">重点项目</button></div></div><div class="campaign-list">${cards}</div><div class="dashboard-empty" hidden>当前筛选条件下没有项目。</div>`}
function projectSelector(label='当前项目'){return `<div class="project-selector"><div><span>${label}</span><strong>Nespresso 冬日暖饮 Campaign</strong><small>Zoe、Claire 协作 · 最后更新 10 分钟前</small></div><button class="ghost" data-action="toast" data-message="项目切换器已打开">切换项目⌄</button></div>`}
function projectsPage(){return `${head('PROJECT WORKSPACE','Projects 工作台','先选择或新建项目，再进入对应工作模块。')}<div class="workspace-launch"><div class="launch-copy"><span class="eyebrow">START HERE</span><h2>从一个项目开始工作</h2><p>选择已有项目继续，或创建新的 Campaign 并邀请协作成员。</p><div class="launch-actions"><button class="primary" data-action="toast" data-message="项目选择器已打开">选择当前项目⌄</button><button class="secondary" data-route="new-project">＋ 新建项目</button></div></div><div class="selected-preview"><span>当前项目</span><strong>Nespresso 冬日暖饮 Campaign</strong><small><i>ZY</i><i>CL</i> 2 位协作者 · 内容执行阶段</small></div></div><section class="workspace-section"><div class="section-title"><div><span>PROJECT MODULES</span><h2>项目工作模块</h2><p>以下内容将读取当前项目的资料与历史版本。</p></div></div><div class="module-grid project-modules"><article class="module-card brief-module" data-route="brief-view"><span class="module-icon">B</span><div><small>01 · INPUT SUMMARY</small><h3>Brief 拆解</h3><p>查看资料解析后整理出的客户背景、目标、卖点、受众和风险项。</p></div><b>查看整理结果 →</b></article><article class="module-card solution-module" data-route="solution-generator"><span class="module-icon">S</span><div><small>02 · PLAN GENERATOR</small><h3>方案生成器</h3><p>在一个连续流程里完成策略方向与 KOL 执行 Brief。</p><div class="mini-steps"><span>策略方向</span><i>→</i><span>执行 Brief</span></div></div><b>进入生成器 →</b></article></div></section><section class="workspace-section"><div class="section-title"><div><span>QUICK CREATION</span><h2>独立内容工具</h2><p>可以自由生成，也可以选择项目读取 Brief 与策略。</p></div></div><div class="module-grid tool-modules"><article class="module-card image-module" data-route="image-generator"><span class="module-icon">▧</span><div><small>VISUAL STUDIO</small><h3>图片生成器</h3><p>生成 Demo 图、Moodboard、构图和视觉氛围参考。</p></div><b>开始生成 →</b></article><article class="module-card copy-module" data-route="copy-generator"><span class="module-icon">Aa</span><div><small>COPY STUDIO</small><h3>文案生成器</h3><p>生成小红书、抖音、微博等不同平台与风格的文案。</p></div><b>开始写作 →</b></article></div></section>`}
function newProject(){return `${head('NEW CAMPAIGN','新建项目','先建立项目资料空间，创建后再进入 Brief 拆解。')}<div class="new-project-shell"><div class="card form-card new-project-form"><div class="form-section"><div class="form-section-head"><span>01</span><div><h3>项目基本信息</h3><p>用于工作台识别与项目排期。</p></div></div><div class="option-grid"><div class="field wide-field"><label>项目名称</label><input placeholder="例如：Nespresso 冬日暖饮 Campaign"></div><div class="field"><label>客户 / 品牌</label><input placeholder="填写品牌名称"></div><div class="field"><label>项目负责人</label><select><option>Zoe Yang（我）</option><option>Claire Li</option><option>Aria Chen</option></select></div><div class="field"><label>开始日期</label><input type="date" value="2026-10-21"></div><div class="field"><label>项目截止日期</label><input type="date" value="2026-11-30"></div></div></div><div class="form-section"><div class="form-section-head"><span>02</span><div><h3>协作成员</h3><p>被邀请的成员会在自己的 Dashboard 看到并共同更新该项目。</p></div></div><div class="member-picker"><button class="member-chip selected"><i>CL</i>Claire Li <b>×</b></button><button class="member-chip"><i>AC</i>Aria Chen</button><button class="member-chip add" data-action="toast" data-message="成员选择器已打开">＋ 添加成员</button></div></div><div class="form-section"><div class="form-section-head"><span>03</span><div><h3>上传项目资料</h3><p>Brief、产品资料和视觉文件会作为后续生成依据。</p></div></div><div class="upload-zone" id="uploadZone"><input id="fileInput" type="file" hidden multiple accept=".xlsx,.xls,.csv,.pdf,.ppt,.pptx,.doc,.docx,.png,.jpg,.jpeg"><div class="upload-icon">⇧</div><h3>拖入文件，或点击上传</h3><p>支持 Excel、PPT、PDF、Word 与图片；单文件最大 50 MB</p><button class="secondary">选择文件</button></div><div id="fileList"></div></div><div class="form-section"><div class="form-section-head"><span>04</span><div><h3>补充信息</h3><p>填写文件中没有说明、但需要 AI 特别注意的内容。</p></div></div><div class="field"><label>项目补充说明</label><textarea placeholder="例如：客户更重视节日送礼场景；避免过度强调促销……"></textarea></div></div><div class="form-actions"><button class="ghost" data-route="projects">取消</button><button class="primary" data-action="createProject">创建项目并解析资料 →</button></div></div><aside class="creation-guide"><span class="eyebrow">创建后将自动进行</span><div><i>1</i><p><strong>资料归档</strong><small>建立独立项目空间</small></p></div><div><i>2</i><p><strong>Brief 解析</strong><small>整理客户需求与风险</small></p></div><div><i>3</i><p><strong>邀请协作者</strong><small>共享同一份项目数据</small></p></div></aside></div>`}
const briefFields=[['项目背景','冬季居家咖啡消费升温，品牌希望强化节日氛围与送礼心智。'],['Campaign 目标','建立“一杯专业咖啡就是冬日生活仪式”的认知，并推动限定风味关注。'],['核心产品','Vertuo 系列咖啡机与冬日限定胶囊。'],['核心卖点','一键获得专业咖啡体验；冬日限定风味；兼顾自用与送礼。'],['必须传递的信息','操作便捷、限定风味、专业咖啡体验。'],['次要信息','机器设计融入居家空间，适合节日礼赠。'],['目标人群','25–38 岁一二线城市品质生活人群，重视居家审美与节日仪式感。'],['品牌调性','克制、精致、温暖，不强调低价促销。'],['内容机会点','下班后的松弛时刻、冬日居家氛围、节日礼赠场景。'],['风险与禁区','避免价格导向、过度促销感，以及无法验证的健康功效表达。']];
function briefReadMarkup(version='V2'){return `<div class="brief-state-head"><div><span class="eyebrow">CONFIRMED BRIEF · ${version}</span><h2>客户需求整理</h2><p>该版本已经确认，下游工具默认读取最新确认版本。</p></div><div class="brief-head-actions"><button class="ghost" data-action="newBriefDraft">补充资料 / 新建解析</button><button class="secondary" data-action="editBriefDraft">基于此版本创建草稿</button></div></div><div class="brief-completeness"><span>资料完整度</span><div class="bar"><i style="width:92%"></i></div><strong>92%</strong></div><div class="brief-field-list">${briefFields.map((x,i)=>`<div class="brief-field"><span>0${i+1}</span><div><h3>${x[0]}</h3><p>${x[1]}</p></div></div>`).join('')}</div><div class="brief-top3"><div><span class="eyebrow">TOP 3 TAKEAWAYS</span><h3>消费者最终应该记住</h3></div>${['在家也能轻松获得专业咖啡体验','冬日限定风味带来节日氛围','既适合自己享用，也适合作为礼物'].map((x,i)=>`<p><i>${i+1}</i>${x}</p>`).join('')}</div>`}
function briefPreparseMarkup(){return `<div class="brief-preparse"><span class="brief-pre-icon">B</span><span class="eyebrow">READY TO ANALYZE</span><h2>资料已就绪，等待开始解析</h2><p>系统不会自动解析。请先确认资料与补充说明，再手动开始。</p><div class="brief-source-list"><div><span>PDF</span><p><strong>Client_Brief_Winter.pdf</strong><small>2.8 MB · 项目创建时上传</small></p><b>已就绪</b></div><div><span>PPT</span><p><strong>Nespresso_Product_2026.pptx</strong><small>8.4 MB · 产品资料</small></p><b>已就绪</b></div></div><div class="field"><label>补充说明（可选）</label><textarea placeholder="补充文件中没有写明，但需要 AI 特别注意的信息……"></textarea></div><div class="brief-pre-actions"><button class="ghost" data-action="addBriefSource">＋ 补充资料</button><button class="primary" data-action="startBriefParse">✦ 开始解析</button></div></div>`}
function briefEditorMarkup(){return `<div class="brief-state-head"><div><span class="eyebrow">DRAFT · 将保存为 V3</span><h2>检查并编辑解析结果</h2><p>修改不会影响 V1、V2；确认后会创建新的正式版本。</p></div><span class="badge orange">未确认草稿</span></div><div class="brief-missing"><b>!</b><div><strong>发现 1 项可能缺失的信息</strong><p>客户没有明确说明 KPI 衡量方式，可以补充后确认，也可以保留为空。</p></div></div><div class="brief-edit-list">${briefFields.map((x,i)=>`<div class="brief-edit-field"><label><span>0${i+1}</span>${x[0]}</label><textarea>${x[1]}</textarea></div>`).join('')}</div><div class="brief-edit-field"><label><span>11</span>消费者最终应该记住的 3 件事</label><textarea>1. 在家也能轻松获得专业咖啡体验\n2. 冬日限定风味带来节日氛围\n3. 既适合自己享用，也适合作为礼物</textarea></div><div class="brief-confirm-bar"><div><strong>确认后保存为 V3</strong><small>V1 与 V2 将继续保留，且不会被覆盖。</small></div><button class="ghost" data-action="cancelBriefDraft">取消草稿</button><button class="primary" data-action="confirmBriefVersion">确认并保存为 V3</button></div>`}
function briefVersionPanel(){return `<aside class="brief-side"><div class="card brief-sources"><div class="brief-side-head"><div><span class="eyebrow">SOURCE MATERIALS</span><h3>项目资料</h3></div><button data-action="addBriefSource">＋</button></div><div><span>PDF</span><p><strong>Client Brief.pdf</strong><small>2.8 MB</small></p></div><div><span>PPT</span><p><strong>Product 2026.pptx</strong><small>8.4 MB</small></p></div><div><span>IMG</span><p><strong>Winter KV.jpg</strong><small>4.1 MB</small></p></div><button class="ghost full-button" data-action="addBriefSource">补充文件或文字</button></div><div class="card brief-versions"><div class="brief-side-head"><div><span class="eyebrow">VERSION HISTORY</span><h3>Brief 版本</h3></div></div><button class="version-item active" data-brief-version="V2"><span>V2</span><p><strong>客户更新卖点</strong><small>当前使用中 · Zoe · 昨天 16:40</small></p><b>✓</b></button><button class="version-item" data-brief-version="V1"><span>V1</span><p><strong>初次解析确认</strong><small>Claire · 10月18日 11:20</small></p></button><div class="version-rule"><strong>版本不会被覆盖</strong><p>新确认内容将作为新版本保存。下游默认读取最新确认版，也可以手动切换。</p></div></div></aside>`}
function briefView(){const isNew=sessionStorage.getItem('ksw_new_brief')==='1';return `${head('PROJECT MODULE','Brief 拆解','手动解析资料、编辑结果并保存不可覆盖的确认版本。','<button class="ghost" data-route="projects">← 返回工作台</button>')}${projectSelector()}<div class="brief-workspace"><section id="briefMain" class="card brief-main">${isNew?briefPreparseMarkup():briefReadMarkup()}</section>${briefVersionPanel()}</div>`}
function solutionGenerator(){return `${head('PROJECT MODULE','方案生成器','策略与执行 Brief 是两个独立工具，可分别进入和保存。','<button class="ghost" data-route="projects">← 返回工作台</button>')}${projectSelector()}<div class="independent-note"><span>独立工作模式</span><p>两个板块都可以直接开始，不要求按顺序完成；需要时都可读取当前项目的 Brief。</p></div><div class="solution-split"><article class="solution-entry strategy-entry" data-route="strategy-generator"><div class="entry-top"><span class="entry-number">01</span><span class="status-pill">可独立使用</span></div><div class="entry-icon">S</div><small>STRATEGY GENERATOR</small><h2>策略生成器</h2><p>从客户需求出发，生成核心理念、传播策略、内容切入方式和适配 KOL 类型。</p><ul><li>核心 Campaign Idea</li><li>多条传播策略路径</li><li>平台、语气与视觉建议</li></ul><button class="primary">进入策略生成器 →</button></article><article class="solution-entry brief-entry" data-route="execution-brief"><div class="entry-top"><span class="entry-number">02</span><span class="status-pill">可独立使用</span></div><div class="entry-icon">EB</div><small>EXECUTION BRIEF</small><h2>执行 Brief 生成器</h2><p>直接选择 KOL 类型、平台和内容风格，生成可交付给达人的执行说明。</p><ul><li>达人类型与内容切入点</li><li>内容结构与必带信息</li><li>拍摄、语气和标题建议</li></ul><button class="primary">进入执行 Brief →</button></article></div>`}
const strategyDirections=[
 {name:'十二年经典，再次如约',tag:'品牌记忆 · 节日经典',idea:'有些味道之所以成为经典，是因为每到冬天，人们都会再次想起它。',insight:'节日限定真正珍贵的并不只是“限时”，而是多年反复出现后形成的共同记忆。消费者期待的，是熟悉风味再次回归时那种“冬天终于开始了”的确认感。',fit:'产品已经连续多年在冬季回归，天然拥有时间积累与熟客心智，适合从“限定新品”升级为“冬日经典”。',product:'从十二年如约回归的记忆切入，再用本季拼配、陈年处理与风味细节说明：经典并非重复，而是被时间不断丰富。',entry:'老朋友回归／我的冬日固定仪式／这些年与它有关的节日记忆',kol:'生活方式达人、咖啡垂类达人、具有长期叙事感的成熟创作者',visual:'红棕与暖金为主色；陈年纸张、旧照片与当季产品并置；用时间刻度呈现多年回归。',tone:'内容侧重时间、记忆与仪式感；语气温暖克制，像与老朋友重逢，避免过度煽情。',risk:'年份、回归次数与产品历史必须以品牌资料为准；避免使用无法证实的“最经典”等绝对化表达。'},
 {name:'时间，是风味的一味配方',tag:'产品工艺 · 风味价值',idea:'让经典不只停留在情怀，也能被一口真正尝见。',insight:'消费者愿意为节日限定买单，需要的不只是包装与情绪，还需要一个具体、可信且容易转述的产品理由。',fit:'陈年咖啡豆、不同产地拼配与成熟风味，为“时间塑造风味”提供了清晰的产品证据。',product:'先解释咖啡豆如何在时间中发展出更深沉的木质与辛香，再自然带出本季产品的三豆拼配和冬日风味层次。',entry:'一杯咖啡里的时间／三种风味如何共同拼出冬日／风味盲测与饮用笔记',kol:'咖啡专业达人、精致生活达人、风味测评与知识型创作者',visual:'麻布袋、咖啡生豆与熟豆、木质桌面；通过三联画展示产地、陈年和最终杯测。',tone:'内容侧重工艺与可感知的味觉描述；专业但不晦涩，用生活化比喻解释风味变化。',risk:'避免将陈年等同于所有消费者都更喜欢；风味描述需与官方杯测信息保持一致。'},
 {name:'一杯咖啡，开启 Holiday 状态',tag:'生活方式 · 场景传播',idea:'Holiday 不是某一天，而是人们允许自己慢下来的一种状态。',insight:'年轻消费者对节日的期待正在从大型庆祝转向轻量、可重复的日常仪式，一杯咖啡就是最低门槛的状态切换。',fit:'产品制作便捷、风味具有冬日联想，能自然进入居家、办公和朋友相聚等多个真实场景。',product:'从“给自己十分钟”开始，通过制作动作、香气和第一口的感受，让产品成为从忙碌进入 Holiday 状态的开关。',entry:'下班后的十分钟／周末居家小聚／办公室里的节日预演',kol:'高质感生活方式达人、居家美学达人、城市日常记录型创作者',visual:'暖光、针织、木质与红色点缀；抓取制作过程、手部动作和第一口的松弛瞬间。',tone:'内容侧重真实场景与情绪转变；语气轻松自然，像分享个人习惯，降低商业感。',risk:'避免把 Holiday 仅等同于西式符号堆砌；产品露出需自然但关键信息不能缺失。'}
];
function strategySetupMarkup(){return `<div class="strategy-setup card"><div><span class="eyebrow">01 · GENERATION SETUP</span><h2>先确定本次策略生成依据</h2><p>默认读取最新确认的 Brief；补充要求可以为空。</p></div><div class="strategy-inputs"><div class="field"><label>读取 Brief 版本</label><select><option>V2 · 客户更新卖点（最新确认）</option><option>V1 · 初次解析确认</option></select></div><div class="field"><label>生成方向数量</label><select><option>3 个方向</option><option>4 个方向</option><option>5 个方向</option></select></div><div class="field wide-field"><label>补充策略要求（可选）</label><textarea placeholder="例如：更强调产品工艺；避免纯节日氛围；需要兼顾小红书与抖音……"></textarea></div></div><div class="strategy-setup-actions"><span>将读取 8 个项目文件 · 协作者可共同编辑</span><button class="primary" onclick="generateStrategiesUI()">✦ 开始生成策略</button></div></div><div id="strategyWorkspace" class="strategy-await card"><span>S</span><h3>等待生成策略方向</h3><p>生成后可先比较方向，再打开某一方向查看完整提案与详细推导。</p></div>`}
function strategyField(label,value,index){return `<section class="strategy-doc-section"><div class="strategy-doc-heading"><span>${String(index).padStart(2,'0')}</span><h3>${label}</h3><button onclick="copyStrategySection(this)">复制本节</button></div><div class="strategy-doc-text" contenteditable="true">${value}</div></section>`}
function strategyDetailMarkup(index=0){const s=strategyDirections[index];const fields=[['策略名称',s.name],['核心逻辑 / INSIGHT',s.insight+' 这意味着策略不应只强调“冬季限定”，而要找到产品与消费者年度记忆之间的关系，让购买成为对熟悉时刻的再次确认。'],['核心理念 / Content Idea',s.idea+' 我们把时间视为整个传播的线索：它既沉淀品牌资产，也参与风味塑造，最终让消费者在当下重新遇见经典。'],['为什么适合该产品',s.fit+' 品牌历史、产品工艺和节日消费场景能够共同支撑这一说法，因此情感价值与产品证据不会彼此割裂。'],['引出产品时的逻辑',s.product+' 传播先建立“时间带来期待”的情绪共识，再逐步落到咖啡豆、拼配和饮用体验，让产品成为结论而不是突兀植入。'],['传播切入点',s.entry+'。每个切入点都可以独立成为一组内容，同时共同强化“每年如约而至”的传播记忆。'],['建议 KOL 类型',s.kol+'。优先选择能够讲述个人经历、呈现真实饮用场景，同时具备稳定审美表达的创作者。'],['视觉建议',s.visual+' 画面需要保留真实生活质感，通过新旧材质、时间痕迹与当季产品的对照，使“经典回归”一眼可见。'],['内容侧重点及语气风格',s.tone+' 先讲消费者熟悉的冬日感受，再讲产品如何参与其中；避免广告口号式表达，保留个人叙述与呼吸感。'],['风险与注意事项',s.risk+' 叙事中涉及的年份、工艺、产地与风味描述均需要回到已确认 Brief 和品牌官方资料核验。']];return `<div class="strategy-detail-head"><div><span class="eyebrow">SELECTED DIRECTION · 0${index+1}</span><h2>${s.name}</h2><p>${s.tag}</p></div><div class="strategy-doc-actions"><button class="ghost" onclick="copyFullStrategy()">复制全文</button><button class="ghost" onclick="backToStrategyCompareUI()">← 返回方向比较</button></div></div><div class="strategy-story"><span>CONTENT IDEA</span><strong>${s.idea}</strong><p>Insight → Content Idea → 产品理由 → 传播表达，形成完整提案叙事。</p></div><div class="strategy-detail-toolbar"><div><button class="active" onclick="switchStrategyLayer(this,false)">PPT 精简版</button><button onclick="switchStrategyLayer(this,true)">查看详细推导</button></div><span id="strategyAutoSaveState">刚刚已自动保存</span></div><article class="strategy-document" oninput="autoSaveStrategyDraft()">${fields.map((x,i)=>strategyField(x[0],x[1],i+1)).join('')}</article><div class="strategy-visual-action"><div><span class="eyebrow">VISUAL DIRECTION</span><strong>把当前视觉建议带入图片生成器</strong><p>离开前会自动暂存；项目、Brief 版本和本策略方向会一起带入。</p></div><button class="secondary" onclick="strategyToImageUI()">制作 Demo 图 →</button></div><div class="strategy-savebar"><div><strong>保存为新的策略版本</strong><small>自动暂存不会创建版本；确认后才保存为 V2，V1 不会被覆盖。</small></div><button class="ghost" onclick="saveStrategyDraftUI()">暂存草稿</button><button class="primary" onclick="saveStrategyVersionUI(this)">确认并保存为 V2</button></div>`}
function strategyCompareMarkup(){return `<div class="strategy-results-head"><div><span class="eyebrow">02 · DIRECTION COMPARISON</span><h2>选择一个方向继续深化</h2><p>三个方向分别成立，可以单独打开、编辑和保存。</p></div><span class="badge green">已生成 3 个方向</span></div><div class="strategy-direction-grid">${strategyDirections.map((s,i)=>`<article class="strategy-direction-card" onclick="openStrategyDirection(${i})"><div><span>0${i+1}</span><em>${s.tag}</em></div><h3>${s.name}</h3><strong>${s.idea}</strong><p>${s.insight}</p><div><small>查看 PPT 精简版与详细推导</small><b>打开方向 →</b></div></article>`).join('')}</div>`}
function strategyVersionPanel(){return `<aside class="card strategy-version-panel"><span class="eyebrow">VERSION HISTORY</span><h3>策略版本</h3><button class="version-item active"><span>V1</span><p><strong>冬日仪式感方向</strong><small>当前使用中 · Zoe · 昨天 16:40</small></p><b>✓</b></button><div id="strategyNewVersion"></div><div class="version-rule"><strong>版本不会被覆盖</strong><p>每次确认都会保存为新版本；执行 Brief 仍可独立选择是否读取。</p></div></aside>`}
function strategyGenerator(){const resume=sessionStorage.getItem('ksw_resume_strategy')==='1';return `${head('STRATEGY GENERATOR','策略生成器','从已确认 Brief 生成提案级策略，并独立保存每一个版本。','<button class="ghost" data-route="solution-generator">← 返回方案生成器</button>')}${projectSelector('关联项目')}<div class="strategy-layout"><section id="strategyMain">${resume?`<section class="card strategy-detail">${strategyDetailMarkup(1)}</section>`:strategySetupMarkup()}</section>${strategyVersionPanel()}</div>`}
function executionBrief(){return `${head('EXECUTION BRIEF','执行 Brief 生成器','无需先完成策略，也可以直接创建达人执行说明。','<button class="ghost" data-route="solution-generator">← 返回方案生成器</button>')}${projectSelector('关联项目')}<div class="brief-builder"><div class="card form-card"><span class="eyebrow">BRIEF SETTINGS</span><h2>设置本次执行方向</h2><div class="option-grid"><div class="field"><label>KOL 类型</label><select><option>高质感生活方式</option><option>咖啡垂类</option><option>美图审美型</option><option>故事型</option></select></div><div class="field"><label>发布平台</label><select><option>小红书</option><option>抖音</option><option>微博</option></select></div><div class="field"><label>内容风格</label><select><option>自然生活化</option><option>专业知识型</option><option>视觉氛围型</option></select></div><div class="field"><label>是否读取策略</label><select><option>不读取，独立生成</option><option>读取已保存策略 V1</option></select></div></div><div class="field"><label>补充执行要求</label><textarea placeholder="例如：需要自然露出产品，避免硬性口播；首图突出冬日氛围……"></textarea></div><button class="primary full-button" data-action="generateBriefMock">✦ 生成执行 Brief</button></div><div class="card brief-output"><div class="result-empty"><span>EB</span><h3>等待生成执行 Brief</h3><p>内容切入点、结构、必带信息和拍摄建议会显示在这里。</p></div></div></div>`}
function creatorPage(type){const image=type==='image',fromStrategy=image&&sessionStorage.getItem('ksw_strategy_visual')==='1';return `${head(image?'VISUAL STUDIO':'COPY STUDIO',image?'图片生成器':'文案生成器',image?'制作 Demo 图、Moodboard 与构图参考。':'生成不同平台、语气和内容角度的文案。','<button class="ghost" data-route="projects">← 返回工作台</button>')}${fromStrategy?'<div class="strategy-context-banner"><span>S</span><div><strong>已带入策略方向：十二年经典，再次如约</strong><p>读取 Brief V2、Content Idea 与视觉建议，可继续修改生成要求。</p></div><button class="ghost" data-action="toast" data-message="策略上下文详情已打开">查看上下文</button></div>':''}<div class="creator-shell"><div class="card creator-controls"><div class="context-switch"><div><span class="eyebrow">PROJECT CONTEXT</span><h3>是否关联项目？</h3></div><label><input type="checkbox" checked data-context-toggle><span></span></label></div><div class="field context-project"><label>读取项目资料</label><select><option>Nespresso 冬日暖饮 Campaign</option><option>Aesop 城市漫游计划</option><option>不关联项目，自由生成</option></select><small>将自动读取该项目已确认的 Brief 与策略方向。</small></div><div class="field"><label>${image?'希望生成什么画面？':'希望生成什么内容？'}</label><textarea placeholder="${image?'例如：冬日居家咖啡场景，暖色自然光，留出产品位置……':'例如：小红书生活方式笔记，松弛自然，突出冬日仪式感……'}">${fromStrategy?'红棕与暖金为主色，结合陈年纸张、旧照片与当季产品，用时间刻度呈现十二年经典回归。':''}</textarea></div><div class="option-grid"><div class="field"><label>${image?'画面类型':'发布平台'}</label><select><option>${image?'Demo 图':'小红书'}</option><option>${image?'Moodboard':'抖音'}</option><option>${image?'构图参考':'微博'}</option></select></div><div class="field"><label>${image?'画幅比例':'生成数量'}</label><select><option>${image?'3:4 竖版':'3 条'}</option><option>${image?'1:1 方图':'5 条'}</option><option>${image?'16:9 横版':'10 条'}</option></select></div></div><button class="primary full-button" data-action="generateMock">✦ ${image?'生成图片方案':'生成文案'}</button></div><div class="card creator-result"><div class="result-empty"><span>${image?'▧':'Aa'}</span><h3>等待生成</h3><p>${image?'生成结果会以卡片形式展示在这里。':'不同风格的文案版本会展示在这里。'}</p></div></div></div>`}
function imageGenerator(){return creatorPage('image')}
function copyGenerator(){return creatorPage('copy')}
const contentItems=[
 {type:'策略',title:'时间，是风味的一味配方',project:'Nespresso 冬日暖饮 Campaign',status:'自动保存草稿',tone:'orange',owner:'我创建的',editor:'Zoe',time:'刚刚',route:'strategy-generator'},
 {type:'策略',title:'冬日仪式感方向 V1',project:'Nespresso 冬日暖饮 Campaign',status:'已保存版本',tone:'green',owner:'我创建的',editor:'Zoe',time:'昨天 16:40',route:'strategy-generator'},
 {type:'执行 Brief',title:'生活方式达人执行方向',project:'Diptyque 节日香氛企划',status:'未确认草稿',tone:'orange',owner:'与我共享',editor:'Mia',time:'今天 11:20',route:'execution-brief'},
 {type:'文案',title:'冬日居家小红书文案',project:'Nespresso 冬日暖饮 Campaign',status:'已保存',tone:'blue',owner:'我创建的',editor:'Zoe',time:'10月22日',route:'copy-generator'},
 {type:'图片方案',title:'Holiday Moodboard',project:'Nespresso 冬日暖饮 Campaign',status:'3 个结果',tone:'blue',owner:'与我共享',editor:'Claire',time:'10月21日',route:'image-generator'}
];
function contentCenter(){return `${head('MY CONTENT','内容中心','集中查看自动保存草稿、正式版本和协作项目中的生成内容。')}<div class="content-summary"><button class="active" onclick="filterContentCenter(this,'all')"><span>全部内容</span><strong>${contentItems.length}</strong></button><button onclick="filterContentCenter(this,'draft')"><span>草稿</span><strong>2</strong></button><button onclick="filterContentCenter(this,'saved')"><span>已保存版本</span><strong>3</strong></button><button onclick="filterContentCenter(this,'recent')"><span>最近使用</span><strong>4</strong></button></div><div class="content-toolbar card"><div class="filter-chips"><button class="active" onclick="filterContentOwner(this,'all')">全部</button><button onclick="filterContentOwner(this,'我创建的')">我创建的</button><button onclick="filterContentOwner(this,'与我共享')">与我共享</button></div><div><select><option>全部项目</option><option>Nespresso 冬日暖饮 Campaign</option><option>Diptyque 节日香氛企划</option></select><select><option>全部类型</option><option>策略</option><option>执行 Brief</option><option>文案</option><option>图片方案</option></select></div></div><div class="content-table card"><div class="content-table-head"><span>内容</span><span>所属项目</span><span>状态</span><span>协作信息</span><span>最后更新</span><span></span></div>${contentItems.map((x,i)=>`<article class="content-row" data-content-item data-owner="${x.owner}" data-content-status="${x.status.includes('草稿')?'draft':'saved'}"><div><i>${x.type==='策略'?'S':x.type==='执行 Brief'?'EB':x.type==='文案'?'Aa':'▧'}</i><p><strong>${x.title}</strong><small>${x.type} · ${x.owner}</small></p></div><span>${x.project}</span><span>${badge(x.status,x.tone)}</span><span><b>${x.editor}</b><small>最后编辑</small></span><span>${x.time}</span>${i===0?'<button class="ghost" onclick="resumeStrategyDraft()">继续编辑</button>':`<button class="ghost" data-route="${x.route}">打开</button>`}</article>`).join('')}</div><div class="content-empty" hidden>当前筛选条件下没有内容。</div>`}
