function render(){if(!sessionStorage.getItem('ksw_logged_in')){nav.innerHTML='';document.querySelector('.sidebar').style.display='none';document.querySelector('main').style.gridColumn='1 / -1';document.querySelector('.topbar').style.display='none';app.innerHTML=loginPage();document.querySelector('#loginBtn').onclick=()=>{const e=document.querySelector('#loginEmail').value,p=document.querySelector('#loginPassword').value;if(!e||!p)return toast('请输入邮箱和密码');sessionStorage.setItem('ksw_logged_in','1');document.querySelector('.sidebar').style.display='flex';document.querySelector('main').style.gridColumn='2';document.querySelector('.topbar').style.display='flex';render()};return}document.querySelector('.sidebar').style.display='flex';document.querySelector('main').style.gridColumn='2';document.querySelector('.topbar').style.display='flex';renderNav();app.innerHTML=(pages[route]||dashboard)();const title=[...navSections.flatMap(s=>s.items)].find(i=>i[0]===route)?.[2]||({'new-project':'新建项目','project-detail':'项目详情'}[route]||'Dashboard');crumb.textContent=`工作台 / ${title}`;wire();window.scrollTo(0,0)}
function go(r){route=r;location.hash=r;render();document.querySelector('.sidebar').classList.remove('open')}
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),2300)}
function wire(){document.querySelectorAll('[data-route]').forEach(el=>el.onclick=()=>go(el.dataset.route));document.querySelectorAll('[data-action="toast"]').forEach(el=>el.onclick=()=>toast(el.dataset.message));document.querySelectorAll('[data-project-toggle]').forEach(btn=>btn.onclick=()=>{const card=btn.closest('.campaign-card'),open=card.classList.toggle('expanded');btn.setAttribute('aria-expanded',String(open));btn.querySelector('i').textContent=open?'⌃':'⌄'});document.querySelectorAll('[data-dash-filter]').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('[data-dash-filter]').forEach(x=>x.classList.remove('active'));btn.classList.add('active');const filter=btn.dataset.dashFilter;let visible=0;document.querySelectorAll('[data-dashboard-card]').forEach(card=>{const p=dashboardProjects.find(x=>x.id===card.querySelector('[data-route="project-detail"]')?.closest('.campaign-card')?.dataset.projectId);const show=filter==='all'||(filter==='attention'&&['overdue','urgent'].includes(card.dataset.urgency))||(filter==='pinned'&&card.querySelector('.pin'));card.hidden=!show;if(show)visible++});const empty=document.querySelector('.dashboard-empty');if(empty)empty.hidden=visible>0});const zone=document.querySelector('#uploadZone'),fi=document.querySelector('#fileInput');if(zone){zone.onclick=()=>fi.click();fi.onchange=()=>{document.querySelector('#fileList').innerHTML=[...fi.files].map(f=>`<div class="project-row"><strong>${f.name}</strong>${badge((f.size/1024/1024).toFixed(1)+' MB','green')}<small>已就绪</small></div>`).join('');toast(`已选择 ${fi.files.length} 个文件`)}}const create=document.querySelector('[data-action="createProject"]');if(create)create.onclick=()=>{sessionStorage.setItem('ksw_new_brief','1');toast('项目已创建，请手动开始 Brief 解析');setTimeout(()=>go('brief-view'),600)};const imp=document.querySelector('#importBtn');if(imp)imp.onclick=()=>{document.querySelector('#importPanel').innerHTML=importPanel();document.querySelector('#importPanel').scrollIntoView({behavior:'smooth'})};document.querySelectorAll('[data-context-toggle]').forEach(toggle=>toggle.onchange=()=>{const field=document.querySelector('.context-project');if(field)field.style.display=toggle.checked?'block':'none'});document.querySelectorAll('[data-action="generateMock"]').forEach(btn=>btn.onclick=()=>{const result=document.querySelector('.creator-result'),isImage=route==='image-generator';result.innerHTML=isImage?'<div class="mock-visual-grid"><div><span>01</span><b>暖调居家场景</b></div><div><span>02</span><b>节日礼赠构图</b></div><div><span>03</span><b>产品静物特写</b></div></div>':'<div class="copy-results"><article><span>生活方式版</span><h3>把冬天，暂停在一杯咖啡里</h3><p>最近开始喜欢把回家后的十分钟留给自己。按下一颗冬日限定胶囊，让香气慢慢铺满房间……</p></article><article><span>视觉种草版</span><h3>冬日居家的仪式感，是暖光和咖啡香</h3><p>不需要复杂准备，一键就能把专业咖啡体验带回家。今天的搭配是奶油色针织和限定风味。</p></article></div>';toast(isImage?'图片方案已生成（Mock）':'文案已生成（Mock）')});document.querySelectorAll('[data-action="generateBriefMock"]').forEach(btn=>btn.onclick=()=>{const result=document.querySelector('.brief-output');result.innerHTML='<div class="generated-brief"><div><span>01</span><h3>内容核心</h3><p>用“下班后的一杯暂停键”呈现冬日居家的松弛时刻，让产品自然成为生活仪式的一部分。</p></div><div><span>02</span><h3>内容结构</h3><p>疲惫回家 → 制作咖啡 → 场景与风味细节 → 一个人的温暖停顿。</p></div><div><span>03</span><h3>必须带出</h3><p>一键操作、冬日限定风味、居家专业咖啡体验。</p></div><div><span>04</span><h3>拍摄建议</h3><p>暖色自然光、木质桌面、手部操作特写；避免正面硬性口播。</p></div></div>';toast('执行 Brief 已独立生成（Mock）')});wireBriefActions();document.querySelectorAll('[data-action="mockImport"]').forEach(x=>x.onclick=()=>toast('示例数据解析完成：1284 行，发现 16 个重复项'))}
function wireBriefActions(){const main=document.querySelector('#briefMain');if(!main)return;const bind=()=>{document.querySelectorAll('[data-action="startBriefParse"]').forEach(btn=>btn.onclick=()=>{main.innerHTML='<div class="brief-analyzing"><span>✦</span><h2>正在解析项目资料</h2><p>识别客户需求、核心卖点、目标人群与风险信息……</p><div class="brief-loading"><i></i></div></div>';setTimeout(()=>{sessionStorage.removeItem('ksw_new_brief');main.innerHTML=briefEditorMarkup();bind();toast('解析完成，请检查并编辑结果')},900)});document.querySelectorAll('[data-action="newBriefDraft"],[data-action="editBriefDraft"]').forEach(btn=>btn.onclick=()=>{main.innerHTML=btn.dataset.action==='newBriefDraft'?briefPreparseMarkup():briefEditorMarkup();bind()});document.querySelectorAll('[data-action="addBriefSource"]').forEach(btn=>btn.onclick=()=>toast('补充资料入口已打开（Mock）'));document.querySelectorAll('[data-action="cancelBriefDraft"]').forEach(btn=>btn.onclick=()=>{main.innerHTML=briefReadMarkup();bind()});document.querySelectorAll('[data-action="confirmBriefVersion"]').forEach(btn=>btn.onclick=()=>{main.innerHTML=briefReadMarkup('V3');const list=document.querySelector('.brief-versions');if(list){list.querySelectorAll('.version-item').forEach(x=>x.classList.remove('active'));list.insertAdjacentHTML('afterbegin','<button class="version-item active" data-brief-version="V3"><span>V3</span><p><strong>补充资料后确认</strong><small>当前使用中 · Zoe · 刚刚</small></p><b>✓</b></button>')}bind();toast('V3 已确认并保存；V1、V2 均已保留')});document.querySelectorAll('[data-brief-version]').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('[data-brief-version]').forEach(x=>x.classList.remove('active'));btn.classList.add('active');main.innerHTML=briefReadMarkup(btn.dataset.briefVersion);bind();toast('正在查看历史版本 '+btn.dataset.briefVersion)})};bind()}
function wireStrategyActions(){const main=document.querySelector('#strategyMain');if(!main)return;const bind=()=>{const generate=document.querySelector('[data-action="generateStrategies"]');if(generate)generate.onclick=()=>{const workspace=document.querySelector('#strategyWorkspace');workspace.innerHTML='<div class="brief-analyzing"><span>✦</span><h2>正在生成策略方向</h2><p>从 Brief 提炼 Insight、Content Idea 与产品引出逻辑……</p><div class="brief-loading"><i></i></div></div>';setTimeout(()=>{workspace.className='card strategy-results';workspace.innerHTML=strategyCompareMarkup();bind();toast('已生成 3 个独立策略方向')},800)};document.querySelectorAll('[data-strategy-index]').forEach(card=>card.onclick=()=>{main.innerHTML=`<section class="card strategy-detail">${strategyDetailMarkup(Number(card.dataset.strategyIndex))}</section>`;bind();window.scrollTo({top:170,behavior:'smooth'})});const back=document.querySelector('[data-action="backToStrategyCompare"]');if(back)back.onclick=()=>{main.innerHTML=`<section class="card strategy-results">${strategyCompareMarkup()}</section>`;bind()};document.querySelectorAll('[data-strategy-layer]').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('[data-strategy-layer]').forEach(x=>x.classList.remove('active'));btn.classList.add('active');document.querySelector('.strategy-detail').classList.toggle('show-detail',btn.dataset.strategyLayer==='detail');toast(btn.dataset.strategyLayer==='detail'?'已展开详细推导':'已切换为 PPT 精简版')});const visual=document.querySelector('[data-action="strategyToImage"]');if(visual)visual.onclick=()=>{sessionStorage.setItem('ksw_strategy_visual','1');go('image-generator')};const save=document.querySelector('[data-action="saveStrategyVersion"]');if(save)save.onclick=()=>{const slot=document.querySelector('#strategyNewVersion');if(slot&&!slot.innerHTML)slot.innerHTML='<button class="version-item active"><span>V2</span><p><strong>十二年经典方向</strong><small>当前使用中 · Zoe · 刚刚</small></p><b>✓</b></button>';save.textContent='已保存为 V2 ✓';save.disabled=true;toast('V2 已确认保存，V1 已完整保留')}};bind()}
function generateStrategiesUI(){const workspace=document.querySelector('#strategyWorkspace');workspace.innerHTML='<div class="brief-analyzing"><span>✦</span><h2>正在生成策略方向</h2><p>从 Brief 提炼 Insight、Content Idea 与产品引出逻辑……</p><div class="brief-loading"><i></i></div></div>';setTimeout(()=>{workspace.className='card strategy-results';workspace.innerHTML=strategyCompareMarkup();toast('已生成 3 个独立策略方向')},800)}
function openStrategyDirection(index){document.querySelector('#strategyMain').innerHTML=`<section class="card strategy-detail">${strategyDetailMarkup(index)}</section>`;window.scrollTo({top:170,behavior:'smooth'})}
function backToStrategyCompareUI(){document.querySelector('#strategyMain').innerHTML=`<section class="card strategy-results">${strategyCompareMarkup()}</section>`}
function switchStrategyLayer(button,detailed){button.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('active'));button.classList.add('active');document.querySelector('.strategy-detail').classList.toggle('show-detail',detailed);toast(detailed?'已展开详细推导':'已切换为 PPT 精简版')}
function autoSaveStrategyDraft(){sessionStorage.setItem('ksw_strategy_draft','1');sessionStorage.setItem('ksw_strategy_draft_time',new Date().toISOString());const state=document.querySelector('#strategyAutoSaveState');if(state)state.textContent='正在自动保存…';clearTimeout(window.strategySaveTimer);window.strategySaveTimer=setTimeout(()=>{if(state)state.textContent='刚刚已自动保存'},450)}
function saveStrategyDraftUI(){autoSaveStrategyDraft();toast('草稿已保存，可在内容中心继续编辑')}
function strategyToImageUI(){autoSaveStrategyDraft();sessionStorage.setItem('ksw_strategy_visual','1');toast('策略草稿已自动保存');setTimeout(()=>go('image-generator'),250)}
function copyStrategySection(button){const text=button.closest('.strategy-doc-section').querySelector('.strategy-doc-text').innerText;navigator.clipboard?.writeText(text);button.textContent='已复制 ✓';setTimeout(()=>button.textContent='复制本节',1200)}
function copyFullStrategy(){const text=[...document.querySelectorAll('.strategy-doc-section')].map(x=>`${x.querySelector('h3').innerText}\n${x.querySelector('.strategy-doc-text').innerText}`).join('\n\n');navigator.clipboard?.writeText(text);toast('策略全文已复制')}
function saveStrategyVersionUI(button){const slot=document.querySelector('#strategyNewVersion');if(slot&&!slot.innerHTML)slot.innerHTML='<button class="version-item active"><span>V2</span><p><strong>十二年经典方向</strong><small>当前使用中 · Zoe · 刚刚</small></p><b>✓</b></button>';button.textContent='已保存为 V2 ✓';button.disabled=true;toast('V2 已确认保存，V1 已完整保留')}
function filterContentCenter(button,status){button.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('active'));button.classList.add('active');let shown=0;document.querySelectorAll('[data-content-item]').forEach((x,i)=>{const visible=status==='all'||status==='recent'&&i<4||x.dataset.contentStatus===status;x.hidden=!visible;if(visible)shown++});document.querySelector('.content-empty').hidden=shown>0}
function filterContentOwner(button,owner){button.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('active'));button.classList.add('active');let shown=0;document.querySelectorAll('[data-content-item]').forEach(x=>{const visible=owner==='all'||x.dataset.owner===owner;x.hidden=!visible;if(visible)shown++});document.querySelector('.content-empty').hidden=shown>0}
function resumeStrategyDraft(){sessionStorage.setItem('ksw_resume_strategy','1');go('strategy-generator')}
window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'dashboard';render()});document.querySelector('#mobileMenu').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');render();
